mitigation.zh:
全部数据值使用预编译语句，整数、枚举与标识符分别做严格类型与允许列表校验，统一外部数据库错误响应。
    // Java：PreparedStatement
    try (PreparedStatement ps = conn.prepareStatement(
            "SELECT * FROM t WHERE k = ?")) {
        ps.setString(1, val);
    }
    // PHP：PDO 预处理
    $st = $pdo->prepare("SELECT * FROM t WHERE k = ?");
    $st->execute([$val]);

参数化查询隔离数据与表达式，统一生产错误响应，撤销不必要的函数与系统目录权限并监控转换错误突增。
    // Java：预编译隔离数据与 SQL 结构
    try (PreparedStatement ps = conn.prepareStatement(
            "SELECT name, price FROM goods WHERE id = ?")) {
        ps.setInt(1, id);
    }
    // PHP：PDO 预处理
    $st = $pdo->prepare("SELECT name, price FROM goods WHERE id = ?");
    $st->execute([$id]);

使用参数化 T-SQL 与类型化存储过程参数，关闭不需要的多语句能力，应用账户最小权限并监控 WAITFOR 与异常 UNION。
    // Java JDBC（SQL Server）
    try (PreparedStatement ps = conn.prepareStatement(
            "SELECT name FROM t WHERE id = ?")) {
        ps.setInt(1, id);
    }
    // PHP PDO sqlsrv
    $st = $pdo->prepare("SELECT name FROM t WHERE id = ?");
    $st->execute([$id]);

使用 PostgreSQL 驱动绑定参数，连接角色最小权限，统一错误映射，设置语句超时并检测异常 pg_sleep 与转换失败。
    // Java JDBC（PostgreSQL）
    try (PreparedStatement ps = conn.prepareStatement(
            "SELECT * FROM t WHERE k = ?")) {
        ps.setString(1, val);
    }
    // PHP PDO + 语句超时
    $pdo->exec("SET statement_timeout = '5s'");
    $st = $pdo->prepare("SELECT * FROM t WHERE k = ?");
    $st->execute([$val]);

使用 SQLite 绑定参数，设置执行预算与并发限制，数据库文件最小权限并监控异常大 BLOB 与长查询。
    // Java JDBC（SQLite）
    try (PreparedStatement ps = conn.prepareStatement(
            "SELECT * FROM t WHERE id = ?")) {
        ps.setLong(1, id);
    }
    // PHP PDO（SQLite）：整数绑定
    $st = $pdo->prepare("SELECT * FROM t WHERE id = ?");
    $st->bindValue(1, $id, PDO::PARAM_INT);
    $st->execute();

使用 Oracle 绑定变量，允许列表映射动态标识符，撤销不必要字典视图、UTL_* 包与网络 ACL，统一 ORA 错误。
    // Java JDBC（Oracle）：绑定变量
    try (PreparedStatement ps = conn.prepareStatement(
            "SELECT * FROM users WHERE name = ?")) {
        ps.setString(1, name);
    }
    -- SQL：回收危险包执行权
    REVOKE EXECUTE ON sys.utl_http FROM app_user;
    REVOKE EXECUTE ON sys.utl_file  FROM app_user;

参数化查询与严格类型绑定，不扩充运算符黑名单；字符集统一规范化，全部等价运算符纳入回归。
    // Java：整数强类型绑定
    try (PreparedStatement ps = conn.prepareStatement(
            "SELECT * FROM t WHERE id = ?")) {
        ps.setLong(1, id);
    }
    // PHP：强制转型后绑定
    $st = $pdo->prepare("SELECT * FROM t WHERE id = ?");
    $st->execute([(int)$id]);

页码、大小、偏移解析为有界整数后绑定参数，排序字段走允许列表，授权过滤后应用最大行数。
    // PHP：分页整数绑定 + 排序白名单
    $size = min(max((int)$req["size"], 1), 100);
    $off  = max((int)$req["offset"], 0);
    $st = $pdo->prepare("SELECT * FROM t WHERE uid=? ORDER BY id LIMIT ? OFFSET ?");
    $st->bindValue(1, $uid, PDO::PARAM_INT);
    $st->bindValue(2, $size, PDO::PARAM_INT);
    $st->bindValue(3, $off, PDO::PARAM_INT);
    $st->execute();

参数化查询与严格类型绑定，设置语句超时、资源组与连接池上限，监控延时函数与条件化长查询。
    // Java
    try (PreparedStatement ps = conn.prepareStatement(
            "SELECT * FROM t WHERE id = ?")) {
        ps.setLong(1, id);
    }
    // PHP（MySQL）：SELECT 语句超时
    $pdo->exec("SET SESSION max_execution_time = 5000");
    $st = $pdo->prepare("SELECT * FROM t WHERE id = ?");
    $st->execute([$id]);

使用固定 XPath 表达式与变量解析器，不拼接路径或谓词；无变量 API 时用经校验的字面量编码器兜底。
    // Java：XPathVariableResolver
    Map<String, Object> vars = Map.of("n", username);
    XPath xp = XPathFactory.newInstance().newXPath();
    xp.setXPathVariableResolver(v -> vars.get(v.getLocalPart()));
    NodeList ns = (NodeList) xp.evaluate(
        "/users/user[@name=$n]", doc, XPathConstants.NODESET);
